package com.gass.jobs;
import android.app.Activity;import android.graphics.Color;import android.graphics.Typeface;import android.media.AudioAttributes;import android.media.MediaPlayer;import android.os.Bundle;import android.view.Gravity;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;
public class RadioActivity extends Activity{
 static final int BG=0xff0a0b0e,PANEL=0xff191b21,GOLD=0xffffbe2d,WHITE=0xfff5f6fa,MUTED=0xffabb2be;
 static final String[] SERVERS={"https://de1.api.radio-browser.info","https://de2.api.radio-browser.info","https://nl1.api.radio-browser.info"};
 EditText search;LinearLayout list;TextView status,now;Button play;MediaPlayer mp;String currentUrl="",currentName="";boolean prepared=false;
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 TextView txt(String s,int z,int c,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,1);return t;}
 android.graphics.drawable.GradientDrawable bg(int c){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(c);d.setCornerRadius(dp(13));d.setStroke(dp(1),0xff3e3728);return d;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(GOLD);b.setAllCaps(false);b.setBackground(bg(PANEL));return b;}
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(15),dp(15),dp(15),dp(12));root.setBackgroundColor(BG);root.addView(txt("📻  GASS-OS RADIO",22,GOLD,true));root.addView(txt("Stations en direct • Tunisie • Europe • Monde",12,MUTED,false));
 LinearLayout row=new LinearLayout(this);search=new EditText(this);search.setSingleLine();search.setHint("Rechercher une station");search.setTextColor(WHITE);search.setHintTextColor(MUTED);search.setBackground(bg(PANEL));row.addView(search,new LinearLayout.LayoutParams(0,dp(48),1));Button go=btn("Chercher");LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(dp(100),dp(48));gp.leftMargin=dp(7);row.addView(go,gp);go.setOnClickListener(v->load(search.getText().toString().trim(),""));search.setOnEditorActionListener((v,a,e)->{load(search.getText().toString().trim(),"");return true;});LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(48));rp.topMargin=dp(12);root.addView(row,rp);
 HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout chips=new LinearLayout(this);String[][] cc={{"Top",""},{"🇹🇳 TN","TN"},{"🇫🇷 FR","FR"},{"🇱🇺 LU","LU"},{"🇩🇿 DZ","DZ"},{"🇲🇦 MA","MA"}};for(String[] c:cc){Button x=btn(c[0]);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(42));p.rightMargin=dp(6);chips.addView(x,p);x.setOnClickListener(v->load("",c[1]));}hs.addView(chips);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,dp(46));hp.topMargin=dp(8);root.addView(hs,hp);
 status=txt("Chargement…",12,MUTED,false);root.addView(status);ScrollView sv=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);sv.addView(list);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));
 LinearLayout dock=new LinearLayout(this);dock.setGravity(Gravity.CENTER_VERTICAL);dock.setPadding(dp(10),dp(6),dp(6),dp(6));dock.setBackground(bg(PANEL));now=txt("Aucune station sélectionnée",13,WHITE,true);dock.addView(now,new LinearLayout.LayoutParams(0,-2,1));play=btn("▶");dock.addView(play,new LinearLayout.LayoutParams(dp(55),dp(46)));play.setOnClickListener(v->{if(mp!=null&&prepared){if(mp.isPlaying()){mp.pause();play.setText("▶");}else{mp.start();play.setText("Ⅱ");}}else if(!currentUrl.isEmpty())playStation(currentName,currentUrl);});LinearLayout.LayoutParams dp1=new LinearLayout.LayoutParams(-1,dp(60));dp1.topMargin=dp(8);root.addView(dock,dp1);setContentView(root);load("","");
 }
 void load(String name,String country){status.setText("Recherche des stations…");list.removeAllViews();new Thread(()->{ArrayList<String[]> rows=new ArrayList<>();String error=null;StringBuilder q=new StringBuilder("/json/stations/search?limit=70&hidebroken=true&order=clickcount&reverse=true");try{if(!name.isEmpty())q.append("&name=").append(URLEncoder.encode(name,"UTF-8"));if(!country.isEmpty())q.append("&countrycode=").append(country);}catch(Exception ignored){}String body=null;for(String s:SERVERS)try{body=get(s+q);break;}catch(Exception e){error=e.getMessage();}if(body!=null)try{JSONArray a=new JSONArray(body);for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String u=o.optString("url_resolved",o.optString("url",""));if(u.startsWith("http"))rows.add(new String[]{o.optString("name","Station"),u,o.optString("country",""),o.optString("codec","")+" "+o.optInt("bitrate",0)+" kb/s"});}}catch(Exception e){error=e.getMessage();}final ArrayList<String[]> result=rows;final String err=error;runOnUiThread(()->show(result,err));}).start();}
 void show(ArrayList<String[]> rows,String err){list.removeAllViews();if(rows.isEmpty()){status.setText(err==null?"Aucune station trouvée":"Réseau indisponible : "+err);return;}status.setText(rows.size()+" stations disponibles");for(String[] s:rows){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(12),dp(10),dp(12),dp(10));c.setBackground(bg(PANEL));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(6);list.addView(c,p);c.addView(txt("📻  "+s[0],15,WHITE,true));c.addView(txt(s[2]+" • "+s[3],11,MUTED,false));c.setOnClickListener(v->playStation(s[0],s[1]));}}
 void playStation(String name,String url){currentName=name;currentUrl=url;prepared=false;now.setText("Connexion : "+name);play.setText("…");release();try{mp=new MediaPlayer();mp.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());mp.setDataSource(url);mp.setOnPreparedListener(p->{prepared=true;p.start();now.setText("En direct : "+currentName);play.setText("Ⅱ");});mp.setOnErrorListener((p,w,e)->{status.setText("Flux indisponible ou bloqué par le diffuseur.");release();play.setText("▶");return true;});mp.prepareAsync();}catch(Exception e){status.setText("Lecture impossible.");release();play.setText("▶");}}
 String get(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setRequestProperty("User-Agent","GASS-JOBS/1.0");try(InputStream in=c.getInputStream();ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)o.write(b,0,n);return o.toString("UTF-8");}finally{c.disconnect();}}
 void release(){if(mp!=null){try{mp.stop();}catch(Exception e){}try{mp.release();}catch(Exception e){}mp=null;}prepared=false;}
 protected void onPause(){if(mp!=null&&prepared&&mp.isPlaying()){mp.pause();play.setText("▶");}super.onPause();}protected void onDestroy(){release();super.onDestroy();}
}